const INPUT = "Step 4: AI call";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"post_body": JSON.stringify({ to: $('Step 3: Rule: assign the owner').first().json.owner, item_id: $('Step 1: Read the queue item').first().json.id, invoice_id: $('Step 1: Read the queue item').first().json.invoice_id, reason_code: $('Step 1: Read the queue item').first().json.reason_code, details: $('Step 1: Read the queue item').first().json.details || '', draft: out.draft, draft_check: out.draft_check }), "done_body": JSON.stringify({ status: 'done', result: $('Step 1: Read the queue item').first().json.id }), "log_body": JSON.stringify({ recipe: 'R7.4', item: $('Step 1: Read the queue item').first().json.id, decision: 'to ' + $('Step 3: Rule: assign the owner').first().json.owner + (out.draft ? ', with a draft' : ', no draft'), rules: { reason_code: $('Step 1: Read the queue item').first().json.reason_code, owner: $('Step 3: Rule: assign the owner').first().json.rule, draft: out.draft_check } }), "failed_body": JSON.stringify({ recipe: 'R7.4', item: $('Step 1: Read the queue item').first().json.id, reason: 'write failed', detail: 'Queue or Teams write failed, never retried; tell the owner by hand', owner: $('Config').first().json.workflow_owner })});
